CREATE OR REPLACE FUNCTION public._organization_monthly_course_limits(p_organization_id uuid)
 RETURNS TABLE(subscription_plan text, max_students integer, max_trainings integer, student_limit_source text, training_limit_source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o record;
BEGIN
  SELECT x.subscription_plan::text AS plan,x.custom_max_students,x.custom_max_trained_per_month
  INTO o FROM public.organizations x WHERE x.id=p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization not found' USING ERRCODE='P0002';END IF;
  subscription_plan:=o.plan;
  max_students:=coalesce(o.custom_max_students,CASE lower(coalesce(o.plan,'free'))
    WHEN 'start' THEN 100 WHEN 'standard' THEN 200 WHEN 'professional' THEN -1 WHEN 'maximum' THEN -1 ELSE 10 END);
  max_trainings:=coalesce(o.custom_max_trained_per_month,CASE lower(coalesce(o.plan,'free'))
    WHEN 'start' THEN 60 WHEN 'standard' THEN 100 WHEN 'professional' THEN -1 WHEN 'maximum' THEN -1 ELSE 10 END);
  student_limit_source:=CASE WHEN o.custom_max_students IS NULL THEN 'plan' ELSE 'custom' END;
  training_limit_source:=CASE WHEN o.custom_max_trained_per_month IS NULL THEN 'plan' ELSE 'custom' END;
  IF EXISTS(SELECT 1 FROM public.organization_billing_agreements a WHERE a.organization_id=p_organization_id
    AND a.effective_from<=(statement_timestamp() AT TIME ZONE 'Europe/Moscow')::date
    AND (a.effective_to IS NULL OR a.effective_to>(statement_timestamp() AT TIME ZONE 'Europe/Moscow')::date)) THEN
    max_students:=-1;max_trainings:=-1;student_limit_source:='postpaid';training_limit_source:='postpaid';
  END IF;
  RETURN NEXT;
END;$function$

CREATE OR REPLACE FUNCTION public.account_deletion_erase_data(p_request_id uuid, p_receipt_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'storage'
AS $function$
DECLARE j public.account_deletion_jobs%ROWTYPE; u uuid; r record; v_org uuid; current_snapshot jsonb;
BEGIN
 SELECT * INTO j FROM public.account_deletion_jobs WHERE id=p_request_id AND receipt_hash=p_receipt_hash FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code','INVALID_RECEIPT'); END IF;
 IF j.consent_version IS DISTINCT FROM 'full-personal-data-v1' THEN RETURN jsonb_build_object('code','CONSENT_REQUIRED'); END IF;
 IF j.state='deleted' THEN RETURN jsonb_build_object('erased',true); END IF;
 IF j.state<>'cleanup_pending' THEN RETURN jsonb_build_object('code','NOT_CONFIRMED'); END IF;
 u:=j.user_id;
 PERFORM pg_advisory_xact_lock(hashtextextended(u::text,42007));
 IF jsonb_array_length(public.account_deletion_files(u))>0 OR EXISTS(SELECT 1 FROM storage.objects o JOIN jsonb_array_elements(j.files) f ON f->>'bucket'=o.bucket_id AND f->>'path'=o.name) THEN RETURN jsonb_build_object('code','DELETION_UNAVAILABLE'); END IF;
 current_snapshot:=public.account_deletion_snapshot(u);
 IF jsonb_array_length(current_snapshot->'blockers')>0 THEN RETURN jsonb_build_object('code','PLAN_CHANGED'); END IF;
 -- Delete the enrollment before lesson progress: the live progress trigger
 -- then has no enrollment to reset. CSZ/issued/shared cases failed in preview.
 PERFORM set_config('sintagma.account_deletion_erase_user',u::text,true);
 PERFORM public.uc_erase_admission_cases(u);
 PERFORM public.uc_erase_identification_data(u);
 DELETE FROM public.audit_logs WHERE entity_id=u::text OR (entity_type='enrollment' AND entity_id IN(SELECT id::text FROM public.enrollments WHERE user_id=u));
 UPDATE public.audit_logs SET user_id='00000000-0000-0000-0000-000000000000',user_name=NULL,ip_address=NULL,user_agent=NULL WHERE user_id=u;
 UPDATE public.role_audit_log SET performed_by=NULL,performed_by_name=NULL,details=CASE WHEN details->>'from_user_id'=u::text THEN details-'from_user_id' ELSE details END WHERE performed_by=u AND target_user_id IS DISTINCT FROM u;
 UPDATE public.student_deletion_log SET deleted_by=NULL,deleted_by_name=NULL,deleted_by_email=NULL WHERE deleted_by=u AND student_id IS DISTINCT FROM u;
 DELETE FROM public.final_test_photo_challenges WHERE user_id=u;
 DELETE FROM public.test_attempts WHERE user_id=u;
 DELETE FROM public.test_attempt_start_requests WHERE user_id=u;
 DELETE FROM public.test_attempt_sessions WHERE user_id=u;
 DELETE FROM public.homework_submissions WHERE student_id=u;
 DELETE FROM public.journal_entries WHERE user_id=u;
 DELETE FROM public.group_class_journal_marks WHERE user_id=u;
 DELETE FROM public.training_plans WHERE user_id=u;
 DELETE FROM public.student_group_memberships WHERE user_id=u;
 DELETE FROM public.student_roster_removals WHERE user_id=u;
 DELETE FROM public.enrollments WHERE user_id=u;
 DELETE FROM public.lesson_progress WHERE user_id=u;
 -- on_enrollment_delete inserts an event; remove it after that trigger.
 DELETE FROM public.enrollment_history WHERE user_id=u;
 DELETE FROM public.organization_monthly_student_assignments WHERE user_id=u;
 DELETE FROM public.organization_monthly_training_completions WHERE user_id=u;
 DELETE FROM public.student_deletion_log WHERE student_id=u;
 DELETE FROM public.support_messages WHERE conversation_id IN (SELECT id FROM public.support_conversations WHERE user_id=u) OR sender_user_id=u;
 DELETE FROM public.support_conversations WHERE user_id=u;
 DELETE FROM public.document_signatures WHERE (sender_user_id=u OR recipient_user_id=u) AND signed_at IS NULL AND sender_signed_at IS NULL AND status<>'signed';
 DELETE FROM public.consent_documents WHERE student_user_id=u;
 DELETE FROM public.org_contracts WHERE student_user_id=u AND approved_at IS NULL AND signed_at IS NULL AND status IN ('draft','cancelled');
 FOR r IN SELECT * FROM (VALUES
  ('admin_org_messages','sender_user_id'),
  ('admin_staff','user_id'),
  ('ai_prompt_templates','user_id'),
  ('ai_tutor_sessions','user_id'),
  ('ai_usage_log','user_id'),
  ('call_log_listens','listener_user_id'),
  ('chat_group_members','user_id'),
  ('chat_group_messages','sender_user_id'),
  ('chat_messages','user_id'),
  ('chat_notification_settings','user_id'),
  ('client_error_logs','user_id'),
  ('company_staff','user_id'),
  ('course_access_log','user_id'),
  ('course_reminders','user_id'),
  ('course_requests','user_id'),
  ('course_review_grants','user_id'),
  ('data_subject_requests','user_id'),
  ('exolve_sip_accounts','user_id'),
  ('final_test_photo_challenges','user_id'),
  ('module_access_overrides','user_id'),
  ('notification_preferences','user_id'),
  ('org_general_messages','sender_user_id'),
  ('org_notifications','user_id'),
  ('org_staff','user_id'),
  ('org_student_messages','sender_user_id'),
  ('org_student_messages','student_user_id'),
  ('organization_offer_acceptances','user_id'),
  ('partner_applications','user_id'),
  ('pending_enrollments','user_id'),
  ('pep_agreements','user_id'),
  ('pipeline_runs','user_id'),
  ('registration_attempts','user_id'),
  ('student_consents','user_id'),
  ('student_frdo_data','user_id'),
  ('student_identity_documents','user_id'),
  ('student_login_history','user_id'),
  ('student_login_tokens','user_id'),
  ('student_notifications','user_id'),
  ('support_requests','user_id'),
  ('testimonials','user_id'),
  ('user_achievements','user_id'),
  ('video_identifications','user_id'),
  ('webinar_participants','user_id')
 ) x(t,c) LOOP
  EXECUTE format('DELETE FROM public.%I WHERE %I=$1',r.t,r.c) USING u;
 END LOOP;
 -- Nullable author references are attribution, not ownership of client data.
 FOR r IN SELECT * FROM (VALUES
  ('admin_generated_documents','created_by'),
  ('ai_settings','updated_by'),
  ('app_settings','updated_by'),
  ('company_documents','uploaded_by'),
  ('consent_documents','created_by'),
  ('course_review_grants','revoked_by'),
  ('enrollment_history','performed_by'),
  ('exolve_sip_accounts','created_by'),
  ('landing_content','updated_by'),
  ('marketplace_settings','updated_by'),
  ('organization_comments','created_by'),
  ('organization_reminders','created_by'),
  ('platform_announcements','created_by'),
  ('sales_tasks','assigned_user_id'),
  ('skillspace_import_jobs','created_by'),
  ('staff_invitations','accepted_user_id'),
  ('student_login_tokens','created_by'),
  ('video_identifications','verified_by')
 ) x(t,c) LOOP
  EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I=$1',r.t,r.c,r.c) USING u;
 END LOOP;
 DELETE FROM public.user_roles WHERE user_id=u;
 DELETE FROM public.profiles WHERE user_id=u;
 -- org_staff DELETE creates a role-audit event: clear it after all staff/profile
 -- triggers; never leave the target UUID hidden in its own account history.
 DELETE FROM public.role_audit_log WHERE target_user_id=u;
 DELETE FROM public.audit_logs WHERE entity_id=u::text;
 IF (j.snapshot->>'emptyOrganization')::boolean THEN
  v_org:=(j.snapshot->>'organizationId')::uuid;
  -- Recheck under the organization lock; a concurrent invitation/registration
  -- must never be swept into this operation.
  PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE organization_id=v_org AND user_id<>u) OR EXISTS(SELECT 1 FROM public.org_staff WHERE organization_id=v_org) THEN RAISE EXCEPTION 'Organization changed during deletion'; END IF;
  DELETE FROM public.organizations WHERE id=v_org;
 END IF;
 DELETE FROM public.uc_identification_write_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND kind IN('subject_erase','reviewer_erase') AND user_id=u;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.account_deletion_personal_row_counts(u)) n WHERE (n->>'count')::bigint>0) THEN RAISE EXCEPTION 'Personal data erasure is incomplete'; END IF;
 UPDATE public.account_deletion_jobs SET data_erased=true WHERE id=j.id;
 RETURN jsonb_build_object('erased',true);
END;$function$

CREATE OR REPLACE FUNCTION public.account_deletion_subject_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE column_name text; target_id uuid; targets uuid[]; pep_targets uuid[];
BEGIN
 -- Sort locks to avoid deadlocks in two-person message rows.
 -- UPDATE may not move a revoked subject's data outside the deletion scope.
 SELECT array_agg(DISTINCT subject_id::uuid ORDER BY subject_id::uuid) INTO targets
 FROM unnest(TG_ARGV) c CROSS JOIN LATERAL (
  VALUES (to_jsonb(NEW)->>c),
         (CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD)->>c END)
 ) subjects(subject_id) WHERE subject_id IS NOT NULL;
 -- A signature may refer to a person's PEP agreement even if its party UUIDs
 -- differ. Keep that exact indirect relationship inside the same write fence.
 IF TG_TABLE_NAME='document_signatures' THEN
  SELECT array_agg(DISTINCT p.user_id) INTO pep_targets FROM public.pep_agreements p
  WHERE p.user_id IS NOT NULL AND p.id IN (
   (to_jsonb(NEW)->>'pep_agreement_id')::uuid,
   CASE WHEN TG_OP='UPDATE' THEN (to_jsonb(OLD)->>'pep_agreement_id')::uuid END);
  SELECT array_agg(DISTINCT x ORDER BY x) INTO targets
  FROM unnest(coalesce(targets,'{}'::uuid[])||coalesce(pep_targets,'{}'::uuid[])) x;
 END IF;
 FOREACH target_id IN ARRAY coalesce(targets,'{}'::uuid[]) LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(target_id::text,42007));
  IF EXISTS(SELECT 1 FROM public.account_deletion_revocations WHERE user_id=target_id) THEN
   -- Only these two real DELETE-trigger event rows may be generated during
   -- service cleanup. The same transaction erases them at the tail. The flag
   -- is transaction-local and never bypasses profile/learning/document writes.
   IF TG_OP='INSERT' AND TG_TABLE_NAME IN ('enrollment_history','role_audit_log')
    AND auth.role()='service_role'
    AND current_setting('sintagma.account_deletion_erase_user',true)=target_id::text THEN CONTINUE; END IF;
   RAISE EXCEPTION 'Account personal data writes are closed' USING ERRCODE='42501';
  END IF;
 END LOOP;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.add_students_to_groups(p_organization_id uuid, p_user_ids uuid[], p_group_ids uuid[])
 RETURNS TABLE(organization_id uuid, group_id uuid, user_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_users uuid[];
  v_groups uuid[];
  v_user uuid;
  v_profile public.profiles;
  v_group uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT COALESCE((
    public.has_role(auth.uid(), 'admin'::public.app_role)
    OR public.is_org_owner(auth.uid(), p_organization_id)
    OR (EXISTS (SELECT 1 FROM public.org_staff s WHERE s.user_id = auth.uid()
      AND s.organization_id = p_organization_id AND (s.expires_at IS NULL OR s.expires_at > now()))
      AND public.has_org_staff_permission(auth.uid(), p_organization_id, 'students.write'))
  ), false) THEN
    RAISE EXCEPTION 'student_group_access_denied' USING ERRCODE = '42501';
  END IF;
  IF p_organization_id IS NULL OR p_user_ids IS NULL OR p_group_ids IS NULL
    OR array_position(p_user_ids, NULL) IS NOT NULL OR array_position(p_group_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'invalid_membership_request' USING ERRCODE = '22023';
  END IF;
  SELECT array_agg(DISTINCT u ORDER BY u) INTO v_users FROM unnest(p_user_ids) u;
  SELECT array_agg(DISTINCT g ORDER BY g) INTO v_groups FROM unnest(p_group_ids) g;
  IF COALESCE(cardinality(v_users), 0) NOT BETWEEN 1 AND 1000
    OR COALESCE(cardinality(v_groups), 0) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'invalid_membership_batch_size' USING ERRCODE = '22023';
  END IF;
  -- Consistent ordering serializes duplicate/repeated bulk requests and tenant moves.
  FOREACH v_user IN ARRAY v_users LOOP
    SELECT * INTO v_profile FROM public.profiles p WHERE p.user_id = v_user FOR UPDATE;
    IF NOT FOUND OR v_profile.organization_id IS DISTINCT FROM p_organization_id
      OR NOT public.is_student_profile(v_user, p_organization_id) THEN
      RAISE EXCEPTION 'student_not_in_organization' USING ERRCODE = '42501';
    END IF;
    IF v_profile.archived_at IS NOT NULL THEN
      RAISE EXCEPTION 'student_archived' USING ERRCODE = '22023';
    END IF;
  END LOOP;
  FOREACH v_group IN ARRAY v_groups LOOP
    PERFORM 1 FROM public.student_groups g
      WHERE g.id = v_group AND g.organization_id = p_organization_id FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'group_not_in_organization' USING ERRCODE = '42501';
    END IF;
  END LOOP;
  INSERT INTO public.student_group_memberships AS target (organization_id, group_id, user_id)
  SELECT p_organization_id, g, u FROM unnest(v_groups) g CROSS JOIN unnest(v_users) u
  WHERE NOT EXISTS (SELECT 1 FROM public.profiles p
    WHERE p.user_id = u AND p.organization_id = p_organization_id AND p.student_group_id = g)
  ON CONFLICT ON CONSTRAINT student_group_memberships_pkey DO NOTHING;
  RETURN QUERY SELECT m.organization_id, m.group_id, m.user_id
    FROM public.student_group_memberships_effective m
    WHERE m.organization_id = p_organization_id
      AND m.group_id = ANY(v_groups) AND m.user_id = ANY(v_users)
    ORDER BY m.group_id, m.user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_organization(_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_course_ids uuid[];
  v_company_ids uuid[];
  v_mp_course_ids uuid[];
BEGIN
  IF NOT public.uc_enrollment_delete_actor_writable() THEN
    RAISE EXCEPTION 'organization_delete_access_denied' USING ERRCODE='42501';
  END IF;
  -- Permission check: only global admins
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admins can delete organizations';
  END IF;

  SELECT array_agg(id) INTO v_course_ids FROM public.courses WHERE organization_id = _org_id;
  SELECT array_agg(id) INTO v_company_ids FROM public.companies WHERE organization_id = _org_id;
  SELECT array_agg(id) INTO v_mp_course_ids FROM public.marketplace_courses WHERE organization_id = _org_id;

  -- Marketplace orders (org as buyer or via its marketplace courses)
  DELETE FROM public.marketplace_orders WHERE buyer_organization_id = _org_id;
  IF v_mp_course_ids IS NOT NULL THEN
    DELETE FROM public.marketplace_orders WHERE marketplace_course_id = ANY(v_mp_course_ids);
    DELETE FROM public.marketplace_course_comments WHERE marketplace_course_id = ANY(v_mp_course_ids);
  END IF;

  -- Course-scoped data (most tables CASCADE on courses but be explicit for safety)
  IF v_course_ids IS NOT NULL THEN
    DELETE FROM public.enrollments WHERE course_id = ANY(v_course_ids);
    DELETE FROM public.course_reminders WHERE course_id = ANY(v_course_ids);
    DELETE FROM public.course_documents WHERE course_id = ANY(v_course_ids);
    DELETE FROM public.course_access_log WHERE course_id = ANY(v_course_ids);
    DELETE FROM public.lessons WHERE course_id = ANY(v_course_ids);
  END IF;

  -- Company-scoped data
  IF v_company_ids IS NOT NULL THEN
    UPDATE public.profiles SET company_id = NULL WHERE company_id = ANY(v_company_ids);
    DELETE FROM public.company_requests WHERE company_id = ANY(v_company_ids);
    DELETE FROM public.company_documents WHERE company_id = ANY(v_company_ids);
    DELETE FROM public.training_plans WHERE company_id = ANY(v_company_ids);
    DELETE FROM public.company_staff WHERE company_id = ANY(v_company_ids);
    DELETE FROM public.staff_invitations WHERE company_id = ANY(v_company_ids);
    DELETE FROM public.role_audit_log WHERE company_id = ANY(v_company_ids);
    UPDATE public.registration_links SET company_id = NULL WHERE company_id = ANY(v_company_ids);
    UPDATE public.course_reminders SET company_id = NULL WHERE company_id = ANY(v_company_ids);
    UPDATE public.webinars SET company_id = NULL WHERE company_id = ANY(v_company_ids);
    UPDATE public.incoming_documents SET related_company_id = NULL WHERE related_company_id = ANY(v_company_ids);
    DELETE FROM public.companies WHERE id = ANY(v_company_ids);
  END IF;

  -- Detach profiles from org
  UPDATE public.profiles SET organization_id = NULL WHERE organization_id = _org_id;

  -- Tables without CASCADE on organization_id
  DELETE FROM public.training_plans WHERE organization_id = _org_id;
  DELETE FROM public.ai_usage_log WHERE organization_id = _org_id;

  -- Final delete (CASCADE handles the rest)
  DELETE FROM public.organizations WHERE id = _org_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_plan_features_on_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  all_categories TEXT[] := ARRAY['courses','students','companies','documents',
    'journals','frdo','links','library','services','settings','student_cabinet','labor_safety','webinars'];
  cat TEXT;
BEGIN
  IF NEW.subscription_plan IS NOT DISTINCT FROM OLD.subscription_plan THEN
    RETURN NEW;
  END IF;

  -- All categories enabled for all plans
  FOREACH cat IN ARRAY all_categories LOOP
    INSERT INTO organization_feature_categories (organization_id, category_id, is_enabled)
    VALUES (NEW.id, cat, true)
    ON CONFLICT (organization_id, category_id)
    DO UPDATE SET is_enabled = true;
  END LOOP;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_user_name text;
  v_org_id uuid;
  v_entity_name text;
  v_action text;
  v_entity_type text;
  v_entity_id text;
  v_details jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  -- Get user name
  SELECT COALESCE(full_name, email, 'Unknown') INTO v_user_name
  FROM profiles WHERE user_id = v_user_id LIMIT 1;

  -- Determine action
  v_action := CASE TG_OP
    WHEN 'INSERT' THEN 'create'
    WHEN 'UPDATE' THEN 'update'
    WHEN 'DELETE' THEN 'delete'
  END;

  -- Table-specific logic
  IF TG_TABLE_NAME = 'courses' THEN
    v_entity_type := 'course';
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
      v_entity_id := OLD.id::text;
      v_entity_name := OLD.title;
    ELSE
      v_org_id := NEW.organization_id;
      v_entity_id := NEW.id::text;
      v_entity_name := NEW.title;
      IF TG_OP = 'UPDATE' AND OLD.is_published IS DISTINCT FROM NEW.is_published THEN
        v_action := CASE WHEN NEW.is_published THEN 'update' ELSE 'update' END;
        v_details := jsonb_build_object('published', NEW.is_published);
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'enrollments' THEN
    v_entity_type := 'enrollment';
    IF TG_OP = 'DELETE' THEN
      v_entity_id := OLD.id::text;
      SELECT organization_id INTO v_org_id FROM courses WHERE id = OLD.course_id LIMIT 1;
      SELECT COALESCE(p.full_name, p.email) INTO v_entity_name FROM profiles p WHERE p.user_id = OLD.user_id LIMIT 1;
    ELSE
      v_entity_id := NEW.id::text;
      SELECT organization_id INTO v_org_id FROM courses WHERE id = NEW.course_id LIMIT 1;
      SELECT COALESCE(p.full_name, p.email) INTO v_entity_name FROM profiles p WHERE p.user_id = NEW.user_id LIMIT 1;
    END IF;

  ELSIF TG_TABLE_NAME = 'profiles' THEN
    v_entity_type := 'student';
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
      v_entity_id := OLD.user_id::text;
      v_entity_name := COALESCE(OLD.full_name, OLD.email);
    ELSE
      v_org_id := NEW.organization_id;
      v_entity_id := NEW.user_id::text;
      v_entity_name := COALESCE(NEW.full_name, NEW.email);
      -- Skip trivial updates (last_visit_at only)
      IF TG_OP = 'UPDATE' AND OLD.full_name IS NOT DISTINCT FROM NEW.full_name 
         AND OLD.email IS NOT DISTINCT FROM NEW.email
         AND OLD.login IS NOT DISTINCT FROM NEW.login
         AND OLD.organization_id IS NOT DISTINCT FROM NEW.organization_id
         AND OLD.company_id IS NOT DISTINCT FROM NEW.company_id THEN
        RETURN NEW;
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'companies' THEN
    v_entity_type := 'company';
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
      v_entity_id := OLD.id::text;
      v_entity_name := OLD.name;
    ELSE
      v_org_id := NEW.organization_id;
      v_entity_id := NEW.id::text;
      v_entity_name := NEW.name;
    END IF;

  ELSIF TG_TABLE_NAME = 'course_documents' THEN
    v_entity_type := 'document';
    IF TG_OP = 'DELETE' THEN
      v_entity_id := OLD.id::text;
      v_entity_name := OLD.name;
      SELECT organization_id INTO v_org_id FROM courses WHERE id = OLD.course_id LIMIT 1;
    ELSE
      v_entity_id := NEW.id::text;
      v_entity_name := NEW.name;
      SELECT organization_id INTO v_org_id FROM courses WHERE id = NEW.course_id LIMIT 1;
    END IF;

  ELSIF TG_TABLE_NAME = 'registration_links' THEN
    v_entity_type := 'link';
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
      v_entity_id := OLD.id::text;
      v_entity_name := OLD.name;
    ELSE
      v_org_id := NEW.organization_id;
      v_entity_id := NEW.id::text;
      v_entity_name := NEW.name;
    END IF;

  ELSIF TG_TABLE_NAME = 'journal_instances' THEN
    v_entity_type := 'journal';
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
      v_entity_id := OLD.id::text;
      v_entity_name := OLD.title;
    ELSE
      v_org_id := NEW.organization_id;
      v_entity_id := NEW.id::text;
      v_entity_name := NEW.title;
    END IF;

  ELSIF TG_TABLE_NAME = 'education_document_records' THEN
    v_entity_type := 'document';
    IF TG_OP = 'DELETE' THEN
      v_org_id := OLD.organization_id;
      v_entity_id := OLD.id::text;
      v_entity_name := OLD.full_name || ' — ' || OLD.document_type;
    ELSE
      v_org_id := NEW.organization_id;
      v_entity_id := NEW.id::text;
      v_entity_name := NEW.full_name || ' — ' || NEW.document_type;
    END IF;

  ELSE
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Only log if we have an org_id
  IF v_org_id IS NOT NULL THEN
    INSERT INTO audit_logs (organization_id, user_id, user_name, action_type, entity_type, entity_id, entity_name, details, user_agent)
    VALUES (v_org_id, v_user_id, v_user_name, v_action, v_entity_type, v_entity_id, v_entity_name, v_details, NULL);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_complete_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.progress >= 100 AND NEW.status != 'completed' THEN
    NEW.status := 'completed';
    NEW.completed_at := now();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_create_education_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_course public.courses%ROWTYPE;
  v_program_source public.group_program_enrollment_snapshots;
  v_association_count integer;
  v_full_name text;
  v_birth_date date;
  v_group_id uuid;
  v_doc_type text;
  v_doc_n integer;
  v_reg_n integer;
  v_max_doc integer;
  v_max_reg integer;
  v_year integer;
BEGIN
  IF NEW.status IS DISTINCT FROM 'completed'
     OR (TG_OP = 'UPDATE' AND OLD.status = 'completed') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_course FROM public.courses WHERE id = NEW.course_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  -- Completion stays successful when provenance or issuance authority is unknown.
  -- Multiple effective associations require explicit group selection; never pick the first.
  SELECT count(*) INTO v_association_count FROM public.student_group_memberships_effective m
  JOIN public.student_groups g ON g.id=m.group_id AND g.organization_id=m.organization_id
  WHERE m.user_id=NEW.user_id AND m.organization_id=v_course.organization_id AND g.course_id=NEW.course_id;
  IF v_association_count<>1 THEN RETURN NEW; END IF;
  SELECT m.group_id INTO v_group_id FROM public.student_group_memberships_effective m JOIN public.student_groups g ON g.id=m.group_id AND g.organization_id=m.organization_id
  WHERE m.user_id=NEW.user_id AND m.organization_id=v_course.organization_id AND g.course_id=NEW.course_id;
  IF NOT coalesce(public.uc_document_has_action(v_course.organization_id,'issue') AND public.uc_document_record_scope(v_course.organization_id,v_group_id,NEW.id,NEW.user_id,NEW.course_id),false) THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_course.organization_id::text, 0));
  v_program_source:=public.uc_program_issuance_source(v_course.organization_id,v_group_id,NEW.id,NEW.user_id,NEW.course_id);
  v_course.title:=v_program_source.program_snapshot->'facts'->>'full_title';
  v_course.frdo_qualification_name:=coalesce(v_program_source.program_snapshot->'facts'->>'qualification',v_program_source.program_snapshot->'facts'->>'profession');
  v_doc_type := CASE v_program_source.program_snapshot->'facts'->>'program_type'
    WHEN 'dpo_upskilling' THEN 'certificate'
    WHEN 'dpo_retraining' THEN 'diploma'
    WHEN 'professional_training' THEN 'qualification'
    ELSE NULL
  END;
  IF v_doc_type IS NULL THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.education_document_records edr
    WHERE edr.enrollment_id = NEW.id
      AND lower(btrim(edr.document_status)) IN ('original', 'оригинал')
      AND edr.deleted_at IS NULL
  ) THEN RETURN NEW; END IF;

  SELECT NULLIF(BTRIM(p.full_name), '')
  INTO v_full_name
  FROM public.profiles p
  WHERE p.user_id = NEW.user_id AND p.organization_id = v_course.organization_id
  LIMIT 1;

  SELECT sfd.birth_date INTO v_birth_date
  FROM public.student_frdo_data sfd
  WHERE sfd.user_id = NEW.user_id AND sfd.organization_id = v_course.organization_id
  LIMIT 1;
  IF v_full_name IS NULL OR v_birth_date IS NULL THEN RETURN NEW; END IF;

  v_year := EXTRACT(YEAR FROM CURRENT_DATE)::integer;
  SELECT COALESCE(MAX((substring(edr.document_number FROM '([0-9]+)$'))::integer), 0)
  INTO v_max_doc
  FROM public.education_document_records edr
  WHERE edr.organization_id = v_course.organization_id
    AND EXTRACT(YEAR FROM edr.issue_date) = v_year AND edr.deleted_at IS NULL;

  INSERT INTO public.document_number_sequences (organization_id, doc_type, year, last_number)
  VALUES (v_course.organization_id, 'edu_doc', v_year, v_max_doc + 1)
  ON CONFLICT (organization_id, doc_type, year)
  DO UPDATE SET last_number = GREATEST(document_number_sequences.last_number + 1, v_max_doc + 1), updated_at = now()
  RETURNING last_number INTO v_doc_n;

  SELECT COALESCE(MAX((substring(edr.reg_number FROM '([0-9]+)$'))::integer), 0)
  INTO v_max_reg
  FROM public.education_document_records edr
  WHERE edr.organization_id = v_course.organization_id
    AND EXTRACT(YEAR FROM edr.issue_date) = v_year AND edr.deleted_at IS NULL;

  INSERT INTO public.document_number_sequences (organization_id, doc_type, year, last_number)
  VALUES (v_course.organization_id, 'edu_reg', v_year, v_max_reg + 1)
  ON CONFLICT (organization_id, doc_type, year)
  DO UPDATE SET last_number = GREATEST(document_number_sequences.last_number + 1, v_max_reg + 1), updated_at = now()
  RETURNING last_number INTO v_reg_n;

  INSERT INTO public.education_document_records (
    organization_id, user_id, course_id, group_id, enrollment_id,
    full_name, birth_date, document_type, document_number, reg_number,
    issue_date, specialty_name, qualification_name, document_status, delivery_method
  ) VALUES (
    v_course.organization_id, NEW.user_id, NEW.course_id, v_group_id, NEW.id,
    v_full_name, v_birth_date, v_doc_type,
    v_year || '/' || LPAD(v_doc_n::text, 6, '0'),
    'ДОК-' || v_year || '/' || LPAD(v_reg_n::text, 4, '0'),
    CURRENT_DATE, v_course.title, v_course.frdo_qualification_name, 'original', 'personal'
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'education document was not auto-created for enrollment %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calc_enrollment_expires_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.access_days IS NOT NULL AND NEW.access_days > 0 THEN
    NEW.expires_at := NEW.started_at + (NEW.access_days || ' days')::interval;
  ELSIF NEW.access_days IS NULL THEN
    NEW.expires_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_course_assignment(p_enrollment_id uuid, p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_enrollment public.enrollments%ROWTYPE;
  v_deleted_id uuid;
  v_relation record;
  v_has_records boolean;
BEGIN
  IF v_actor IS NULL OR p_organization_id IS NULL OR NOT coalesce((
    public.has_role(v_actor, 'admin'::public.app_role)
    OR public.is_org_owner(v_actor, p_organization_id)
    OR (
      EXISTS (SELECT 1 FROM public.org_staff os
        WHERE os.user_id = v_actor AND os.organization_id = p_organization_id
          AND (os.expires_at IS NULL OR os.expires_at > now()))
      AND public.has_org_staff_permission(v_actor, p_organization_id, 'students.write')
    )
  ), false) THEN
    RAISE EXCEPTION 'assignment_forbidden' USING ERRCODE = '42501';
  END IF;
  -- Guards must observe writes that completed while waiting for the locks.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'assignment_requires_read_committed' USING ERRCODE = '25000';
  END IF;
  -- These learning tables have no enrollment FK. Briefly prevent concurrent
  -- inserts/updates while checking them; a busy learner causes a retry, not loss.
  LOCK TABLE public.lessons, public.lesson_progress, public.test_attempts IN SHARE MODE;
  FOR v_relation IN
    SELECT c.oid::regclass AS relation FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname IN (
        'test_attempt_sessions', 'homework_submissions', 'course_access_log', 'education_document_records'
      ) AND c.relkind IN ('r', 'p') ORDER BY c.oid
  LOOP
    EXECUTE format('LOCK TABLE %s IN SHARE MODE', v_relation.relation);
  END LOOP;
  -- Block concurrent changes to the incoming FK set while inspecting it.
  LOCK TABLE public.enrollments IN ROW EXCLUSIVE MODE;
  SELECT e.* INTO v_enrollment FROM public.enrollments e
    JOIN public.courses c ON c.id = e.course_id
    JOIN public.profiles p ON p.user_id = e.user_id
    WHERE e.id = p_enrollment_id AND c.organization_id = p_organization_id
      AND p.organization_id = p_organization_id
    FOR UPDATE OF e FOR SHARE OF c, p;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'assignment_not_found' USING ERRCODE = 'P0002';
  END IF;
  -- started_at is the assignment date, populated by DEFAULT now(); it is not
  -- proof that a learner started studying.
  IF coalesce(v_enrollment.progress, 0) <> 0 OR coalesce(v_enrollment.time_spent, 0) <> 0
    OR v_enrollment.status IS DISTINCT FROM 'active' OR v_enrollment.completed_at IS NOT NULL
    OR EXISTS (SELECT 1 FROM public.lesson_progress lp JOIN public.lessons l ON l.id = lp.lesson_id
      WHERE lp.user_id = v_enrollment.user_id AND l.course_id = v_enrollment.course_id)
    OR EXISTS (SELECT 1 FROM public.test_attempts ta JOIN public.lessons l ON l.id = ta.lesson_id
      WHERE ta.user_id = v_enrollment.user_id AND l.course_id = v_enrollment.course_id) THEN
    RAISE EXCEPTION 'assignment_has_learning_history' USING ERRCODE = '23514';
  END IF;
  FOR v_relation IN
    SELECT c.oid::regclass AS relation, c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname IN ('test_attempt_sessions', 'homework_submissions', 'course_access_log')
        AND c.relkind IN ('r', 'p') ORDER BY c.oid
  LOOP
    IF v_relation.relname = 'test_attempt_sessions' THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s r JOIN public.lessons l ON l.id = r.lesson_id WHERE r.user_id = $1 AND l.course_id = $2)', v_relation.relation)
        INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    ELSIF v_relation.relname = 'homework_submissions' THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE student_id = $1 AND course_id = $2)', v_relation.relation)
        INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    ELSE
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE user_id = $1 AND course_id = $2)', v_relation.relation)
        INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    END IF;
    IF v_has_records THEN
      RAISE EXCEPTION 'assignment_has_learning_history' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  -- Also preserve historical documents whose enrollment_id was cleared earlier.
  IF to_regclass('public.education_document_records') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.education_document_records WHERE user_id = $1 AND course_id = $2)'
      INTO v_has_records USING v_enrollment.user_id, v_enrollment.course_id;
    IF v_has_records THEN
      RAISE EXCEPTION 'assignment_has_dependent_records' USING ERRCODE = '23514';
    END IF;
  END IF;
  -- Inspect every incoming FK, including SET NULL and future relations. The row
  -- lock prevents a concurrent child insert from passing its FK check.
  FOR v_relation IN
    SELECT con.conkey, con.confkey, ns.nspname, rel.relname, att.attname
      FROM pg_constraint con
      JOIN pg_class rel ON rel.oid = con.conrelid
      JOIN pg_namespace ns ON ns.oid = rel.relnamespace
      LEFT JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = con.conkey[1]
      WHERE con.contype = 'f' AND con.confrelid = 'public.enrollments'::regclass
  LOOP
    IF cardinality(v_relation.conkey) <> 1 OR cardinality(v_relation.confkey) <> 1
      OR v_relation.confkey[1] <> (SELECT attnum FROM pg_attribute
        WHERE attrelid = 'public.enrollments'::regclass AND attname = 'id') THEN
      RAISE EXCEPTION 'assignment_has_dependent_records' USING ERRCODE = '23514';
    END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = $1)',
      v_relation.nspname, v_relation.relname, v_relation.attname)
      INTO v_has_records USING p_enrollment_id;
    IF v_has_records THEN
      RAISE EXCEPTION 'assignment_has_dependent_records' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  DELETE FROM public.enrollments WHERE id = p_enrollment_id RETURNING id INTO v_deleted_id;
  IF v_deleted_id IS DISTINCT FROM p_enrollment_id OR EXISTS (
    SELECT 1 FROM public.enrollments WHERE id = p_enrollment_id
  ) THEN
    RAISE EXCEPTION 'assignment_verification_failed' USING ERRCODE = 'P0001';
  END IF;
  RETURN jsonb_build_object('cancelled', true, 'enrollmentId', v_deleted_id,
    'organizationId', p_organization_id, 'userId', v_enrollment.user_id, 'courseId', v_enrollment.course_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_postpaid_study_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n jsonb:=to_jsonb(NEW); o jsonb; learner uuid; course uuid; org uuid; meaningful boolean:=false;
BEGIN
 IF TG_OP='UPDATE' THEN o:=to_jsonb(OLD); ELSE o:='{}'::jsonb; END IF;
 learner:=COALESCE((n->>'user_id')::uuid,(n->>'student_id')::uuid);
 -- A teacher review, administrative import or backdated payload is not a
 -- learner interaction. Imported historical evidence is reviewed separately.
 IF auth.uid() IS NULL OR learner IS DISTINCT FROM auth.uid() OR NOT public.account_deletion_access_allowed() THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='lesson_progress' THEN
  meaningful:=(COALESCE((n->>'completed')::boolean,false) AND NOT COALESCE((o->>'completed')::boolean,false))
    OR COALESCE((n->>'time_spent')::numeric,0)>COALESCE((o->>'time_spent')::numeric,0)
    OR COALESCE((n->>'video_position')::numeric,0)>COALESCE((o->>'video_position')::numeric,0);
 ELSIF TG_TABLE_NAME='enrollments' THEN
  meaningful:=COALESCE((n->>'progress')::numeric,0)>COALESCE((o->>'progress')::numeric,0)
   OR COALESCE((n->>'time_spent')::numeric,0)>COALESCE((o->>'time_spent')::numeric,0)
   OR (n->>'status'='completed' AND COALESCE(o->>'status','')<>'completed');
 ELSIF TG_TABLE_NAME='homework_submissions' THEN
  meaningful:=TG_OP='INSERT' AND (length(btrim(COALESCE(n->>'content','')))>0 OR COALESCE(n->'attachments','[]'::jsonb)<>'[]'::jsonb);
 ELSE meaningful:=TG_OP='INSERT'; END IF;
 IF NOT meaningful THEN RETURN NEW; END IF;
 course:=(n->>'course_id')::uuid;
 IF course IS NULL THEN SELECT course_id INTO course FROM public.lessons WHERE id=(n->>'lesson_id')::uuid; END IF;
 SELECT c.organization_id INTO org FROM public.courses c JOIN public.profiles p ON p.organization_id=c.organization_id AND p.user_id=learner
 WHERE c.id=course AND EXISTS(SELECT 1 FROM public.enrollments e WHERE e.course_id=c.id AND e.user_id=learner) AND public.can_access_course_as_learner(c.id);
 IF org IS NOT NULL THEN PERFORM public.postpaid_append_event(org,'study',learner,course,TG_TABLE_NAME,n->>'id',clock_timestamp()); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.check_enrollment_achievements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_completed_courses INTEGER;
BEGIN
  -- Check if course was just completed
  IF NEW.status = 'completed' AND (OLD IS NULL OR OLD.status != 'completed') THEN
    -- Award graduate achievement
    PERFORM award_achievement(NEW.user_id, 'graduate');

    -- Count total completed courses
    SELECT COUNT(*) INTO v_completed_courses
    FROM enrollments
    WHERE user_id = NEW.user_id AND status = 'completed';

    IF v_completed_courses >= 3 THEN
      PERFORM award_achievement(NEW.user_id, 'knowledge_collector');
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_course_reminder_on_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period integer;
  v_org_id uuid;
  v_company_id uuid;
  v_advance_days integer;
BEGIN
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    SELECT retraining_period_months, organization_id, reminder_advance_days
    INTO v_period, v_org_id, v_advance_days
    FROM public.courses WHERE id = NEW.course_id;

    IF v_period IS NOT NULL AND v_period > 0 THEN
      SELECT company_id INTO v_company_id
      FROM public.profiles WHERE user_id = NEW.user_id LIMIT 1;

      INSERT INTO public.course_reminders (
        course_id, enrollment_id, user_id, organization_id, company_id,
        completed_at, reminder_date
      ) VALUES (
        NEW.course_id, NEW.id, NEW.user_id, v_org_id, v_company_id,
        COALESCE(NEW.completed_at, now()),
        ((COALESCE(NEW.completed_at, now()) + (v_period || ' months')::interval) - (COALESCE(v_advance_days, 30) || ' days')::interval)::date
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_org_course_completion_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_course_title text;
  v_student_name text;
BEGIN
  -- Fire only when transitioning INTO 'completed'.
  IF NEW.status IS DISTINCT FROM 'completed' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'completed' THEN
    RETURN NEW;
  END IF;

  SELECT c.organization_id, c.title
    INTO v_org_id, v_course_title
  FROM public.courses c
  WHERE c.id = NEW.course_id;

  IF v_org_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(NULLIF(TRIM(p.full_name), ''), 'Ученик')
    INTO v_student_name
  FROM public.profiles p
  WHERE p.user_id = NEW.user_id
    AND p.organization_id = v_org_id
  LIMIT 1;

  IF v_student_name IS NULL THEN
    v_student_name := 'Ученик';
  END IF;

  INSERT INTO public.org_notifications (
    organization_id, user_id, type, title, message, related_id, is_read
  )
  VALUES (
    v_org_id,
    NEW.user_id,
    'course_completed',
    'Ученик завершил курс',
    v_student_name || ' завершил(а) курс «' || COALESCE(v_course_title, 'без названия') || '»',
    NEW.course_id,
    false
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_student_profile_with_capacity(p_organization_id uuid, p_user_id uuid, p_full_name text, p_email text, p_login text, p_generated_password text, p_company_id uuid, p_student_group_id uuid, p_region text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limits record;v_current integer:=0;v_existing_org uuid;v_existing_archived timestamptz;
  v_existing boolean:=false;v_group_confirmed boolean:=true;v_detail text;
  v_month date:=date_trunc('month',statement_timestamp() AT TIME ZONE 'Europe/Moscow')::date;
  v_jwt_role text:=coalesce(current_setting('request.jwt.claim.role',true),current_setting('request.jwt.claims',true)::jsonb->>'role');
BEGIN
  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501';END IF;
  IF p_organization_id IS NULL OR p_user_id IS NULL THEN RAISE EXCEPTION 'organization_id and user_id are required';END IF;
  -- Match the existing account-deletion subject lock before the org quota lock.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,42007));
  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text,42));
  SELECT * INTO v_limits FROM public._organization_monthly_course_limits(p_organization_id);
  SELECT p.organization_id,p.archived_at INTO v_existing_org,v_existing_archived
    FROM public.profiles p WHERE p.user_id=p_user_id FOR UPDATE;
  IF v_existing_org IS NOT NULL AND v_existing_org<>p_organization_id THEN
    RETURN jsonb_build_object('success',false,'code','PROFILE_IN_OTHER_ORG','message','Профиль пользователя уже привязан к другой организации.',
      'max_students',v_limits.max_students,'is_unlimited',v_limits.max_students=-1,'limit_source',v_limits.student_limit_source);
  END IF;
  SELECT coalesce(u.assigned_students,0) INTO v_current FROM public.organization_monthly_course_usage u
    WHERE u.organization_id=p_organization_id AND u.month_start=v_month;
  v_current:=coalesce(v_current,0);
  v_existing:=v_existing_org=p_organization_id;
  IF v_existing AND v_existing_archived IS NOT NULL THEN
    RETURN jsonb_build_object('success',false,'code','STUDENT_ARCHIVED','message','Ученик находится в архиве. Восстановите его из архива вручную.',
      'current_students',v_current,'max_students',v_limits.max_students,'is_unlimited',v_limits.max_students=-1,'limit_source',v_limits.student_limit_source);
  END IF;
  IF v_existing THEN
    UPDATE public.profiles SET full_name=coalesce(nullif(p_full_name,''),full_name),email=coalesce(nullif(p_email,''),email),
      company_id=coalesce(p_company_id,company_id),region=coalesce(nullif(p_region,''),region)
      WHERE user_id=p_user_id;
  ELSE
    INSERT INTO public.profiles(user_id,full_name,email,login,generated_password,organization_id,company_id,region)
    VALUES(p_user_id,p_full_name,nullif(p_email,''),nullif(p_login,''),nullif(p_generated_password,''),p_organization_id,p_company_id,nullif(p_region,''))
    ON CONFLICT(user_id) DO UPDATE SET full_name=excluded.full_name,email=coalesce(excluded.email,public.profiles.email),
      login=coalesce(excluded.login,public.profiles.login),generated_password=coalesce(excluded.generated_password,public.profiles.generated_password),
      organization_id=excluded.organization_id,company_id=coalesce(excluded.company_id,public.profiles.company_id),region=coalesce(excluded.region,public.profiles.region)
    WHERE public.profiles.organization_id IS NULL OR public.profiles.organization_id=p_organization_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'profile organization changed during registration' USING ERRCODE='40001';END IF;
  END IF;
  INSERT INTO public.user_roles(user_id,role) VALUES(p_user_id,'student'::public.app_role) ON CONFLICT(user_id) DO NOTHING;
  -- Group membership may automatically assign a course. A full course quota
  -- rolls back only that requested membership, never the unlimited personal file.
  IF p_student_group_id IS NOT NULL THEN
    BEGIN
      UPDATE public.profiles SET student_group_id=p_student_group_id WHERE user_id=p_user_id;
    EXCEPTION WHEN SQLSTATE 'P0001' THEN
      GET STACKED DIAGNOSTICS v_detail=PG_EXCEPTION_DETAIL;
      IF v_detail IS DISTINCT FROM 'STUDENT_ASSIGNMENT_LIMIT_EXCEEDED' THEN RAISE;END IF;
      v_group_confirmed:=false;
    END;
  END IF;
  SELECT coalesce(u.assigned_students,0) INTO v_current FROM public.organization_monthly_course_usage u
    WHERE u.organization_id=p_organization_id AND u.month_start=v_month;
  RETURN jsonb_build_object('success',true,'is_existing',coalesce(v_existing,false),'profile_persisted',true,
    'group_assignment_confirmed',v_group_confirmed,
    'group_assignment_error',CASE WHEN v_group_confirmed THEN NULL ELSE 'STUDENT_ASSIGNMENT_LIMIT_EXCEEDED' END,
    'current_students',coalesce(v_current,0),'max_students',v_limits.max_students,'is_unlimited',v_limits.max_students=-1,'limit_source',v_limits.student_limit_source);
END;$function$

CREATE OR REPLACE FUNCTION public.csz_guard_course_anchor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT ((TG_OP<>'INSERT' AND OLD.id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[]))
    OR (TG_OP<>'DELETE' AND NEW.id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[]))) THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'S022: READ COMMITTED required' USING ERRCODE='25000'; END IF;
  PERFORM pg_advisory_xact_lock(7630559,178);
  IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.organization_id IS DISTINCT FROM OLD.organization_id)) THEN
    RAISE EXCEPTION 'S022: protected course anchor cannot be removed/reassigned' USING ERRCODE='42501';
  END IF;
  IF auth.uid() IS NULL OR NOT public.can_access_organization(NEW.organization_id,'courses.write') THEN
    RAISE EXCEPTION 'S022: courses.write required for protected course' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.csz_guard_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_staff boolean; v_org uuid; v_credit timestamptz; v_total integer; v_done integer; v_ceiling integer;
BEGIN
  IF NOT ((TG_OP<>'INSERT' AND OLD.course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[]))
    OR (TG_OP<>'DELETE' AND NEW.course_id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[]))) THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'S022: READ COMMITTED required' USING ERRCODE='25000'; END IF;
  PERFORM pg_advisory_xact_lock(7630559,178);
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'S022: protected enrollment/history cannot be deleted' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.course_id IS DISTINCT FROM OLD.course_id THEN
      RAISE EXCEPTION 'S022: immutable enrollment identity' USING ERRCODE='42501';
    END IF;
    -- Executor owns the row lock already; explicit lock documents the shared lock contract.
    PERFORM 1 FROM public.enrollments WHERE id=OLD.id FOR UPDATE;
  END IF;
  SELECT organization_id INTO v_org FROM public.courses WHERE id=NEW.course_id;
  v_staff:=coalesce(public.can_access_course(NEW.course_id,'students.write'),false);
  IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=NEW.user_id AND organization_id=v_org) THEN
    RAISE EXCEPTION 'S022: invalid enrollment actor/tenant' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NOT v_staff OR NEW.status<>'active' OR NEW.progress<>0 OR NEW.completed_at IS NOT NULL THEN
      RAISE EXCEPTION 'S022: only staff may create an initial enrollment' USING ERRCODE='42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT v_staff AND (auth.uid() IS DISTINCT FROM OLD.user_id OR NOT public.can_access_course_as_learner(OLD.course_id)
    OR NEW.access_days IS DISTINCT FROM OLD.access_days OR NEW.started_at IS DISTINCT FROM OLD.started_at
    OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN
    RAISE EXCEPTION 'S022: enrollment identity/access cannot be self-edited' USING ERRCODE='42501';
  END IF;
  IF NEW.status='active' AND NEW.progress=0 AND NEW.completed_at IS NULL
    AND (OLD.status='completed' OR OLD.progress<>0 OR OLD.completed_at IS NOT NULL) THEN
    IF NOT v_staff OR EXISTS(SELECT 1 FROM public.lesson_progress lp JOIN public.lessons l ON l.id=lp.lesson_id
      WHERE lp.user_id=NEW.user_id AND l.course_id=NEW.course_id) THEN
      RAISE EXCEPTION 'S022: staff reset must clear target lesson progress first' USING ERRCODE='42501';
    END IF;
    RETURN NEW; -- existing S001 AFTER trigger revokes the active credit
  END IF;
  IF NEW.status NOT IN ('active','completed') AND NOT v_staff THEN
    RAISE EXCEPTION 'S022: learner cannot change enrollment lifecycle' USING ERRCODE='42501';
  END IF;
  IF OLD.status='completed' AND NEW.status IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION 'S022: use staff reset to reopen a completed enrollment' USING ERRCODE='42501';
  END IF;
  SELECT credited_at INTO v_credit FROM public.course_manual_credits WHERE enrollment_id=NEW.id AND revoked_at IS NULL;
  SELECT count(*),count(*) FILTER (WHERE lp.completed AND
    (l.type<>'homework' OR v_credit IS NOT NULL OR public.csz_latest_homework_approved(NEW.user_id,NEW.course_id,l.id)))
    INTO v_total,v_done FROM public.lessons l
    LEFT JOIN public.lesson_progress lp ON lp.lesson_id=l.id AND lp.user_id=NEW.user_id WHERE l.course_id=NEW.course_id;
  v_ceiling:=CASE WHEN v_total=0 THEN 0 ELSE round(v_done*100.0/v_total)::integer END;
  IF NEW.progress<0 OR NEW.progress>v_ceiling
    OR ((NEW.progress=100 OR NEW.status='completed') AND (v_total=0 OR v_done<>v_total)) THEN
    RAISE EXCEPTION 'S022: enrollment exceeds accepted lesson progress' USING ERRCODE='23514';
  END IF;
  IF NEW.status='completed' THEN
    IF OLD.status='completed' THEN NEW.completed_at:=coalesce(OLD.completed_at,v_credit,clock_timestamp());
    ELSE NEW.completed_at:=coalesce(v_credit,clock_timestamp()); END IF;
  ELSE NEW.completed_at:=NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.csz_guard_protected_truncate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- Statement guard: RLS and row triggers do not protect TRUNCATE (including CASCADE).
  -- A pre-existing REPEATABLE READ snapshot must not miss a concurrently created anchor.
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'S022: READ COMMITTED required for TRUNCATE' USING ERRCODE='25000'; END IF;
  PERFORM pg_advisory_xact_lock(7630559,178);
  IF EXISTS(SELECT 1 FROM public.courses WHERE id=ANY(ARRAY['7630559a-6caf-42e7-97f9-1cd0e4598c39','7e5bc4e6-0629-4186-9745-a821cbe7255a']::uuid[])) THEN
    RAISE EXCEPTION 'S022: TRUNCATE forbidden while protected course exists' USING ERRCODE='42501';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_course_insert_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_plan text;
  v_custom_max integer;
  v_max_courses integer;
  v_current_courses integer;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
       AND NEW.system_key IS NOT DISTINCT FROM OLD.system_key
    THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'Organization is required for course creation'
      USING ERRCODE = '23502';
  END IF;

  -- A trusted system insert is not part of the commercial quota. The separate
  -- guard_course_system_key trigger rejects this marker for ordinary callers.
  IF NEW.system_key IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(subscription_plan, 'free'), custom_max_courses
    INTO v_plan, v_custom_max
  FROM public.organizations
  WHERE id = NEW.organization_id
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('course-limit:' || NEW.organization_id::text, 0)
  );

  v_max_courses := COALESCE(
    v_custom_max,
    CASE v_plan
      WHEN 'free' THEN 3
      WHEN 'start' THEN 15
      WHEN 'standard' THEN 30
      WHEN 'professional' THEN -1
      WHEN 'maximum' THEN -1
      ELSE 3
    END
  );

  IF EXISTS (
    SELECT 1 FROM public.organization_billing_agreements agreement
    WHERE agreement.organization_id = NEW.organization_id
      AND agreement.effective_from <= (now() AT TIME ZONE 'Europe/Moscow')::date
      AND (agreement.effective_to IS NULL
        OR agreement.effective_to > (now() AT TIME ZONE 'Europe/Moscow')::date)
  ) THEN
    v_max_courses := -1;
  END IF;

  IF v_max_courses <> -1 THEN
    SELECT count(*)::integer
      INTO v_current_courses
    FROM public.courses
    WHERE organization_id = NEW.organization_id
      AND system_key IS NULL;

    IF v_current_courses >= GREATEST(v_max_courses, 0) THEN
      RAISE EXCEPTION 'maximum course limit reached'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.enforce_organization_monthly_course_quota()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org uuid;v_month date:=(date_trunc('month',statement_timestamp() AT TIME ZONE 'Europe/Moscow'))::date;
  v_assigned boolean:=false;v_completed boolean:=false;v_limits record;v_usage record;
BEGIN
  IF TG_OP='INSERT' THEN
    v_assigned:=true;
    v_completed:=(NEW.status='completed');
  ELSE
    v_assigned:=NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.course_id IS DISTINCT FROM OLD.course_id
      OR (OLD.expires_at IS NOT NULL AND (OLD.started_at IS NOT NULL OR NEW.access_days IS DISTINCT FROM OLD.access_days)
        AND (NEW.expires_at IS NULL OR NEW.expires_at>OLD.expires_at))
      OR (OLD.started_at IS NOT NULL AND NEW.started_at>OLD.started_at)
      OR (OLD.status IN ('expired','cancelled','revoked') AND NEW.status='active');
    v_completed:=NEW.status='completed' AND
      (OLD.status IS DISTINCT FROM 'completed' OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.course_id IS DISTINCT FROM OLD.course_id);
  END IF;
  IF NOT v_assigned AND NOT v_completed THEN RETURN NEW;END IF;
  SELECT c.organization_id INTO v_org FROM public.courses c WHERE c.id=NEW.course_id;
  IF v_org IS NULL OR NOT public.is_student_profile(NEW.user_id,v_org) THEN RETURN NEW;END IF;
  -- The subject fence already takes this lock for enrollment writes. Taking it
  -- here as well keeps erasure/registration serialized in one documented order.
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,42007));
  PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,42));
  SELECT * INTO v_limits FROM public._organization_monthly_course_limits(v_org);
  INSERT INTO public.organization_monthly_course_usage(organization_id,month_start)
  VALUES(v_org,v_month) ON CONFLICT DO NOTHING;
  SELECT * INTO v_usage FROM public.organization_monthly_course_usage
    WHERE organization_id=v_org AND month_start=v_month FOR UPDATE;
  IF v_assigned AND NOT EXISTS(SELECT 1 FROM public.organization_monthly_student_assignments
    WHERE organization_id=v_org AND month_start=v_month AND user_id=NEW.user_id) THEN
    IF v_limits.max_students<>-1 AND v_usage.assigned_students>=v_limits.max_students THEN
      RAISE EXCEPTION USING ERRCODE='P0001',
        MESSAGE='Достигнут месячный лимит учеников с назначенными курсами. Личные дела можно создавать и хранить без ограничений.',
        DETAIL='STUDENT_ASSIGNMENT_LIMIT_EXCEEDED';
    END IF;
    INSERT INTO public.organization_monthly_student_assignments
      (organization_id,month_start,user_id,first_assigned_at,source)
    VALUES(v_org,v_month,NEW.user_id,statement_timestamp(),'assignment');
    UPDATE public.organization_monthly_course_usage SET assigned_students=assigned_students+1
      WHERE organization_id=v_org AND month_start=v_month;
  END IF;
  IF v_completed AND NOT EXISTS(SELECT 1 FROM public.organization_monthly_training_completions
    WHERE organization_id=v_org AND month_start=v_month AND enrollment_id=NEW.id) THEN
    IF v_limits.max_trainings<>-1 AND v_usage.completed_trainings>=v_limits.max_trainings THEN
      RAISE EXCEPTION USING ERRCODE='P0001',
        MESSAGE='Достигнут месячный лимит завершённых обучений. Обратитесь к администратору организации.',
        DETAIL='TRAINING_COMPLETION_LIMIT_EXCEEDED';
    END IF;
    INSERT INTO public.organization_monthly_training_completions
      (organization_id,month_start,enrollment_id,user_id,first_completed_at,source)
    VALUES(v_org,v_month,NEW.id,NEW.user_id,statement_timestamp(),'completion');
    UPDATE public.organization_monthly_course_usage SET completed_trainings=completed_trainings+1
      WHERE organization_id=v_org AND month_start=v_month;
  END IF;
  RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.get_organization_student_capacity(p_organization_id uuid, p_requested_count integer DEFAULT 1)
 RETURNS TABLE(current_students integer, max_students integer, is_unlimited boolean, can_add boolean, remaining_students integer, subscription_plan text, limit_source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan text;
  v_custom integer;
  v_plan_limit integer;
  v_max integer;
  v_source text;
  v_current integer := 0;
  v_requested integer := GREATEST(COALESCE(p_requested_count, 1), 0);
  v_uid uuid := auth.uid();
  v_jwt_role text := COALESCE(
    current_setting('request.jwt.claim.role', true),
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role')
  );
  v_is_service boolean := (v_jwt_role = 'service_role');
  v_allowed boolean := false;
  v_month date := date_trunc('month',statement_timestamp() AT TIME ZONE 'Europe/Moscow')::date;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF v_is_service THEN
    v_allowed := true;
  ELSIF v_uid IS NOT NULL THEN
    IF public.has_role(v_uid, 'admin'::public.app_role) THEN
      v_allowed := true;
    ELSIF EXISTS (
      SELECT 1 FROM public.user_roles ur
      JOIN public.profiles p ON p.user_id = ur.user_id
      WHERE ur.user_id = v_uid
        AND ur.role = 'organization'::public.app_role
        AND p.organization_id = p_organization_id
    ) THEN
      v_allowed := true;
    ELSIF EXISTS (
      SELECT 1 FROM public.org_staff os
      WHERE os.user_id = v_uid
        AND os.organization_id = p_organization_id
        AND (os.expires_at IS NULL OR os.expires_at > now())
    ) AND (
      public.has_org_staff_permission(v_uid, p_organization_id, 'students.read')
      OR public.has_org_staff_permission(v_uid, p_organization_id, 'students.write')
    ) THEN
      v_allowed := true;
    ELSIF EXISTS (
      SELECT 1 FROM public.companies c
      WHERE c.organization_id = p_organization_id
        AND (
          c.user_id = v_uid
          OR public.has_company_access(v_uid, c.id, 'viewer'::public.company_staff_role)
        )
    ) THEN
      v_allowed := true;
    END IF;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'access denied to organization capacity' USING ERRCODE = '42501';
  END IF;


  SELECT l.subscription_plan,l.max_students,l.student_limit_source INTO v_plan,v_max,v_source
  FROM public._organization_monthly_course_limits(p_organization_id) l;
  SELECT coalesce(u.assigned_students,0) INTO v_current
  FROM public.organization_monthly_course_usage u
  WHERE u.organization_id=p_organization_id AND u.month_start=v_month;
  v_current:=coalesce(v_current,0);

  current_students := v_current;
  max_students := v_max;
  subscription_plan := v_plan;
  limit_source := v_source;
  is_unlimited := (v_max = -1);

  IF is_unlimited THEN
    remaining_students := -1;
    can_add := true;
  ELSIF v_max <= 0 THEN
    remaining_students := 0;
    can_add := false;
  ELSE
    remaining_students := GREATEST(v_max - v_current, 0);
    can_add := (v_current + v_requested) <= v_max;
  END IF;

  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_organization_training_capacity(p_organization_id uuid, p_requested_count integer DEFAULT 1)
 RETURNS TABLE(current_trainings integer, max_trainings integer, is_unlimited boolean, can_complete boolean, remaining_trainings integer, subscription_plan text, limit_source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE l record;requested integer:=greatest(coalesce(p_requested_count,1),0);
BEGIN
  -- Reuse the existing tenant/staff/company authorization; no extra grants.
  PERFORM 1 FROM public.get_organization_student_capacity(p_organization_id,0);
  SELECT * INTO l FROM public._organization_monthly_course_limits(p_organization_id);
  SELECT coalesce(u.completed_trainings,0) INTO current_trainings FROM public.organization_monthly_course_usage u
    WHERE u.organization_id=p_organization_id
      AND u.month_start=date_trunc('month',statement_timestamp() AT TIME ZONE 'Europe/Moscow')::date;
  current_trainings:=coalesce(current_trainings,0);max_trainings:=l.max_trainings;
  subscription_plan:=l.subscription_plan;limit_source:=l.training_limit_source;
  is_unlimited:=max_trainings=-1;
  remaining_trainings:=CASE WHEN is_unlimited THEN -1 ELSE greatest(max_trainings-current_trainings,0) END;
  can_complete:=is_unlimited OR current_trainings+requested<=max_trainings;
  RETURN NEXT;
END;$function$

CREATE OR REPLACE FUNCTION public.guard_course_system_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Ordinary course transfers remain available. A marked system course may
    -- not be moved to another tenant by a regular course editor.
    IF NEW.system_key IS NULL
       AND OLD.system_key IS NULL
    THEN
      RETURN NEW;
    END IF;

    IF NEW.system_key IS NOT DISTINCT FROM OLD.system_key
       AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
    THEN
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' AND NEW.system_key IS NULL THEN
    RETURN NEW;
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_role('admin'::public.app_role, auth.uid())
     OR session_user IN ('postgres', 'supabase_admin')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Only trusted platform processes may change a course system key'
    USING ERRCODE = '42501';
END
$function$

CREATE OR REPLACE FUNCTION public.guard_organization_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.balance < 0 THEN
    RAISE EXCEPTION 'Organization balance cannot be negative'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' AND NEW.balance = 0 THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.balance IS NOT DISTINCT FROM OLD.balance THEN
    RETURN NEW;
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_role('admin'::public.app_role, auth.uid())
     OR current_user IN ('postgres', 'supabase_admin')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Only trusted billing processes may change organization balance'
    USING ERRCODE = '42501';
END
$function$

CREATE OR REPLACE FUNCTION public.guard_organization_course_quota_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF auth.role() = 'service_role'
       OR public.has_role('admin'::public.app_role, auth.uid())
       OR session_user IN ('postgres', 'supabase_admin')
    THEN
      RETURN NEW;
    END IF;

    -- Public registration may provide ordinary profile/requisite fields, but
    -- never billing, quota or feature entitlements. Normalize those fields to
    -- the canonical free-plan baseline instead of trusting request columns.
    NEW.subscription_plan := 'free';
    NEW.custom_max_courses := NULL;
    NEW.custom_max_students := NULL;
    NEW.custom_max_trained_per_month := NULL;
    NEW.custom_ai_generations_limit := NULL;
    NEW.custom_storage_limit_bytes := NULL;
    NEW.is_paid := false;
    NEW.paid_until := NULL;
    NEW.tariff_type := 'free';
    NEW.monthly_price := 0;
    NEW.tariff_custom_label := NULL;
    NEW.custom_price := NULL;
    NEW.custom_discount := NULL;
    NEW.storage_limit_bytes := 104857600;
    NEW.ai_tokens_limit := 100000;
    NEW.enabled_features := '[]'::jsonb;
    NEW.custom_enabled_categories := '{}'::text[];
    NEW.ai_enabled := true;
    NEW.frdo_enabled := true;
    RETURN NEW;
  END IF;

  IF NEW.subscription_plan IS NOT DISTINCT FROM OLD.subscription_plan
     AND NEW.custom_max_courses IS NOT DISTINCT FROM OLD.custom_max_courses
     AND NEW.custom_max_students IS NOT DISTINCT FROM OLD.custom_max_students
     AND NEW.custom_max_trained_per_month IS NOT DISTINCT FROM OLD.custom_max_trained_per_month
     AND NEW.custom_ai_generations_limit IS NOT DISTINCT FROM OLD.custom_ai_generations_limit
     AND NEW.custom_storage_limit_bytes IS NOT DISTINCT FROM OLD.custom_storage_limit_bytes
     AND NEW.is_paid IS NOT DISTINCT FROM OLD.is_paid
     AND NEW.paid_until IS NOT DISTINCT FROM OLD.paid_until
     AND NEW.tariff_type IS NOT DISTINCT FROM OLD.tariff_type
     AND NEW.monthly_price IS NOT DISTINCT FROM OLD.monthly_price
     AND NEW.tariff_custom_label IS NOT DISTINCT FROM OLD.tariff_custom_label
     AND NEW.custom_price IS NOT DISTINCT FROM OLD.custom_price
     AND NEW.custom_discount IS NOT DISTINCT FROM OLD.custom_discount
     AND NEW.storage_limit_bytes IS NOT DISTINCT FROM OLD.storage_limit_bytes
     AND NEW.ai_tokens_limit IS NOT DISTINCT FROM OLD.ai_tokens_limit
     AND NEW.enabled_features IS NOT DISTINCT FROM OLD.enabled_features
     AND NEW.custom_enabled_categories IS NOT DISTINCT FROM OLD.custom_enabled_categories
     AND NEW.ai_enabled IS NOT DISTINCT FROM OLD.ai_enabled
     AND NEW.frdo_enabled IS NOT DISTINCT FROM OLD.frdo_enabled
  THEN
    RETURN NEW;
  END IF;

  IF auth.role() = 'service_role'
     OR public.has_role('admin'::public.app_role, auth.uid())
     OR session_user IN ('postgres', 'supabase_admin')
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Only platform billing administrators may change organization entitlements'
    USING ERRCODE = '42501';
END
$function$

CREATE OR REPLACE FUNCTION public.invalidate_marketplace_course_validation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_old_course_id uuid;
  v_new_course_id uuid;
  v_old_lesson_id uuid;
  v_new_lesson_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'courses' THEN
    v_old_course_id := OLD.id;
    v_new_course_id := NEW.id;
  ELSIF TG_TABLE_NAME IN ('course_modules', 'lessons', 'course_documents') THEN
    IF TG_OP <> 'INSERT' THEN
      v_old_course_id := OLD.course_id;
    END IF;
    IF TG_OP <> 'DELETE' THEN
      v_new_course_id := NEW.course_id;
    END IF;
  ELSIF TG_TABLE_NAME IN ('test_questions', 'lesson_attachments') THEN
    IF TG_OP <> 'INSERT' THEN
      v_old_lesson_id := OLD.lesson_id;
      SELECT l.course_id INTO v_old_course_id
      FROM public.lessons l
      WHERE l.id = v_old_lesson_id;
    END IF;
    IF TG_OP <> 'DELETE' THEN
      v_new_lesson_id := NEW.lesson_id;
      SELECT l.course_id INTO v_new_course_id
      FROM public.lessons l
      WHERE l.id = v_new_lesson_id;
    END IF;
  END IF;

  UPDATE public.marketplace_courses mc
  SET is_validated = false
  WHERE mc.is_validated = true
    AND mc.course_id IN (v_old_course_id, v_new_course_id);

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.log_enrollment_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.enrollment_history (enrollment_id, user_id, course_id, action, performed_by)
    VALUES (NEW.id, NEW.user_id, NEW.course_id, 'enrolled', auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.enrollment_history (enrollment_id, user_id, course_id, action, performed_by)
    VALUES (OLD.id, OLD.user_id, OLD.course_id, 'unenrolled', auth.uid());
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_student_registration_details(p_organization_id uuid, p_user_id uuid, p_actor_id uuid, p_department text DEFAULT NULL::text, p_snils text DEFAULT NULL::text, p_birth_date date DEFAULT NULL::date, p_confirm_identity boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_role text := COALESCE(NULLIF(auth.jwt()->>'role', ''), NULLIF(current_setting('request.jwt.claim.role', true), ''), '');
  v_department text := NULLIF(btrim(p_department), '');
  v_snils text := NULLIF(btrim(p_snils), '');
  v_profile public.profiles;
  v_identification public.video_identifications;
  v_frdo_context uuid;
BEGIN
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'service_role_required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.uc_student_frdo_staff_can_write(p_actor_id,p_organization_id,p_user_id,'students.write')
    OR(p_confirm_identity IS TRUE AND NOT public.uc_student_frdo_staff_can_write(p_actor_id,p_organization_id,p_user_id,'documents.write')) THEN
    RAISE EXCEPTION 'student_details_access_denied' USING ERRCODE = '42501';
  END IF;
  IF p_confirm_identity IS TRUE THEN
    PERFORM public.uc_identification_lock_mutation(p_actor_id,p_organization_id,p_user_id);
  END IF;
  -- Serialize repeated imports/confirmation and prevent a concurrent archive/tenant move.
  SELECT * INTO v_profile FROM public.profiles WHERE user_id = p_user_id FOR UPDATE;
  IF NOT FOUND OR v_profile.organization_id IS DISTINCT FROM p_organization_id
     OR NOT public.is_student_profile(p_user_id, p_organization_id) THEN
    RAISE EXCEPTION 'student_not_in_organization' USING ERRCODE = '42501';
  END IF;
  IF v_profile.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'student_archived' USING ERRCODE = '22023';
  END IF;
  IF length(v_department) > 200 OR v_department ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'invalid_department' USING ERRCODE = '22023';
  END IF;
  IF v_snils IS NOT NULL THEN
    IF v_snils !~ '^[0-9[:space:]-]+$' THEN
      RAISE EXCEPTION 'invalid_snils' USING ERRCODE = '22023';
    END IF;
    v_snils := regexp_replace(v_snils, '[[:space:]-]', '', 'g');
    IF length(v_snils) <> 11 THEN
      RAISE EXCEPTION 'invalid_snils' USING ERRCODE = '22023';
    END IF;
    v_snils := substr(v_snils, 1, 3) || '-' || substr(v_snils, 4, 3) || '-' || substr(v_snils, 7, 3) || ' ' || substr(v_snils, 10, 2);
  END IF;
  IF p_birth_date > CURRENT_DATE OR p_birth_date < DATE '0001-01-01' THEN
    RAISE EXCEPTION 'invalid_birth_date' USING ERRCODE = '22023';
  END IF;

  IF v_department IS NOT NULL THEN
    UPDATE public.profiles SET department = v_department WHERE user_id = p_user_id;
  END IF;
  IF v_snils IS NOT NULL OR p_birth_date IS NOT NULL THEN
    IF auth.role() IS DISTINCT FROM 'service_role' OR auth.uid() IS NOT NULL OR NOT public.uc_student_frdo_actor_can_write(p_actor_id,p_organization_id,p_user_id,false) THEN
      RAISE EXCEPTION 'frdo_write_access_denied' USING ERRCODE='42501';
    END IF;
    INSERT INTO public.uc_student_frdo_write_contexts(kind,organization_id,user_id,actor_id)
    VALUES('registration_details',p_organization_id,p_user_id,p_actor_id) RETURNING id INTO v_frdo_context;
    INSERT INTO public.student_frdo_data AS existing (user_id, organization_id, snils, birth_date)
    VALUES (p_user_id, p_organization_id, v_snils, p_birth_date)
    ON CONFLICT (user_id, organization_id) DO UPDATE SET
      snils = COALESCE(EXCLUDED.snils, existing.snils),
      birth_date = COALESCE(EXCLUDED.birth_date, existing.birth_date);
    DELETE FROM public.uc_student_frdo_write_contexts WHERE id=v_frdo_context;
  END IF;

  IF p_confirm_identity IS TRUE THEN
    v_identification.id:=public.uc_registration_identification_claim(p_organization_id,p_user_id,p_actor_id);
    SELECT v.* INTO v_identification FROM public.video_identifications v WHERE v.id=v_identification.id;
  END IF;
  RETURN jsonb_build_object('success', true, 'user_id', p_user_id,
    'organization_id', p_organization_id, 'identity_confirmed', p_confirm_identity IS TRUE,
    'identification_id', v_identification.id);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_default_org_menu_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.menu_settings IS NULL OR NEW.menu_settings = '{}'::jsonb THEN
    NEW.menu_settings := jsonb_build_object(
      'courseViewMode', 'grid',
      'courseFolderMode', 'folders'
    );
  ELSE
    IF NOT (NEW.menu_settings ? 'courseFolderMode') THEN
      NEW.menu_settings := NEW.menu_settings || jsonb_build_object('courseFolderMode', 'folders');
    END IF;
    IF NOT (NEW.menu_settings ? 'courseViewMode') THEN
      NEW.menu_settings := NEW.menu_settings || jsonb_build_object('courseViewMode', 'grid');
    END IF;
  END IF;
  RETURN NEW;
